package com.remzone.blink.tv;

import android.content.*;
import android.database.Cursor;
import android.database.sqlite.SQLiteDatabase;
import org.json.*;
import mobile.Mobile;
import java.util.*;

/** App-private bounded journal. Recording never opens a network connection. */
final class DiagnosticJournal {
    private static Context context;private static SQLiteDatabase db;private static String session;private static long began;
    static synchronized void init(Context c){if(db!=null)return;context=c.getApplicationContext();db=context.openOrCreateDatabase("diagnostics.db",0,null);db.execSQL("CREATE TABLE IF NOT EXISTS sessions(id TEXT PRIMARY KEY,created INTEGER,version TEXT,build TEXT)");db.execSQL("CREATE TABLE IF NOT EXISTS events(id TEXT PRIMARY KEY,session TEXT,at INTEGER,source TEXT,event TEXT,fields TEXT,pending INTEGER)");db.execSQL("CREATE INDEX IF NOT EXISTS event_session ON events(session,at)");newSession();record("app.launch",new JSONObject());}
    private static void newSession(){session=UUID.randomUUID().toString();began=System.currentTimeMillis();String version="1",build="1";try{android.content.pm.PackageInfo p=context.getPackageManager().getPackageInfo(context.getPackageName(),0);version=p.versionName;build=String.valueOf(android.os.Build.VERSION.SDK_INT>=28?p.getLongVersionCode():p.versionCode);}catch(Exception ignored){}ContentValues v=new ContentValues();v.put("id",session);v.put("created",began);v.put("version",version);v.put("build",build);db.insertOrThrow("sessions",null,v);Mobile.setDiagnosticSession(session);prune();}
    private static void prune(){db.execSQL("DELETE FROM sessions WHERE created < ? OR id NOT IN (SELECT id FROM sessions ORDER BY created DESC LIMIT 10)",new Object[]{System.currentTimeMillis()-7L*86400000});db.execSQL("DELETE FROM events WHERE session NOT IN (SELECT id FROM sessions)");}
    static synchronized void begin(Context c,JSONObject saved){init(c);newSession();try{JSONObject destination=saved.optJSONObject("diagnosticDestination");if(destination==null){String url="profile".equals(saved.optString("mode"))?ProfilesStore.selected(saved).optString("subscriptionURL"):saved.optString("url");destination=DiagnosticProtocol.destination(url);}saveDestination(session,destination);}catch(Exception ignored){}record("connection.begin",fields("mode","vk".equals(saved.optString("mode","vk"))?1:0));}
    private static void saveDestination(String id,JSONObject destination)throws Exception{new SecureStore(context).update(saved->{JSONObject all=saved.optJSONObject("diagnosticSessions");if(all==null)all=new JSONObject();all.put(id,new JSONObject(destination.toString()));Set<String> live=new HashSet<>();try(Cursor rows=db.rawQuery("SELECT id FROM sessions",null)){while(rows.moveToNext())live.add(rows.getString(0));}List<String> keys=new ArrayList<>();all.keys().forEachRemaining(keys::add);for(String key:keys)if(!live.contains(key))all.remove(key);saved.put("diagnosticSessions",all);});}
    static synchronized void configure(Context c,String raw)throws Exception{init(c);JSONObject destination=DiagnosticProtocol.destination(raw);if(!"grant".equals(destination.getString("kind")))throw new Exception();new SecureStore(context).update(o->o.put("diagnosticDestination",destination));try(Cursor rows=db.rawQuery("SELECT id FROM sessions",null)){while(rows.moveToNext())saveDestination(rows.getString(0),destination);}}
    static JSONObject fields(String key,long value){try{return new JSONObject().put(key,value);}catch(Exception e){return new JSONObject();}}
    static synchronized void record(String event,JSONObject fields){recordNative(session,System.currentTimeMillis(),"app",event,fields);}
    private static void recordNative(String id,long at,String source,String event,JSONObject fields){if(db==null||id==null||!DiagnosticProtocol.EVENTS.contains(event))return;try{ContentValues v=new ContentValues();v.put("id",UUID.randomUUID().toString());v.put("session",id);v.put("at",at);v.put("source",source);v.put("event",event);v.put("fields",DiagnosticProtocol.numeric(fields==null?new JSONObject():fields).toString());v.put("pending",1);db.insertOrThrow("events",null,v);db.execSQL("DELETE FROM events WHERE session = ? AND id NOT IN (SELECT id FROM events WHERE session = ? ORDER BY at DESC LIMIT 500)",new Object[]{id,id});}catch(Exception ignored){}}
    static synchronized void drain(){if(db==null)return;db.beginTransaction();try{JSONArray events=new JSONArray(Mobile.drainDiagnosticEventsJSON());for(int i=0;i<events.length();i++){JSONObject e=events.getJSONObject(i);String id=e.optString("sessionId",session);try(Cursor c=db.rawQuery("SELECT id FROM sessions WHERE id = ?",new String[]{id})){if(c.moveToFirst())recordNative(id,e.optLong("occurredAt",System.currentTimeMillis()),"native",e.optString("event"),e.optJSONObject("fields"));}}db.setTransactionSuccessful();}catch(Exception ignored){}finally{db.endTransaction();}}
    static synchronized void heartbeat(){drain();try{JSONObject f=new JSONObject(Mobile.runtimeStatsJSON()).put("txBytes",StateStore.tx).put("rxBytes",StateStore.rx);recordNative(session,System.currentTimeMillis(),"app","extension.heartbeat",f);}catch(Exception ignored){}}
    static synchronized int pending(){if(db==null)return 0;try(Cursor c=db.rawQuery("SELECT count(*) FROM events WHERE pending = 1",null)){return c.moveToFirst()?c.getInt(0):0;}}
    static synchronized String preview(){if(db==null)return "";StringBuilder text=new StringBuilder();try(Cursor c=db.rawQuery("SELECT event,fields FROM events ORDER BY at DESC LIMIT 35",null)){while(c.moveToNext())text.append(c.getString(0)).append(" · ").append(c.getString(1)).append('\n');}return text.toString();}
    static synchronized void reset(Context c)throws Exception{init(c);if(StateStore.active()||TunnelService.hasLiveTunnel())throw new Exception();db.beginTransaction();try{db.delete("events",null,null);db.delete("sessions",null,null);db.setTransactionSuccessful();}finally{db.endTransaction();}new SecureStore(context).update(o->o.remove("diagnosticSessions"));Mobile.drainDiagnosticEventsJSON();newSession();}
    static synchronized JSONArray snapshot()throws Exception{drain();JSONArray result=new JSONArray();try(Cursor sessions=db.rawQuery("SELECT id,created,version,build FROM sessions ORDER BY created DESC",null)){while(sessions.moveToNext()){String id=sessions.getString(0);JSONArray events=new JSONArray();try(Cursor rows=db.rawQuery("SELECT id,at,source,event,fields FROM events WHERE session = ? AND pending = 1 ORDER BY at LIMIT 500",new String[]{id})){while(rows.moveToNext())events.put(new JSONObject().put("id",rows.getString(0)).put("occurredAt",rows.getLong(1)).put("elapsedMs",Math.max(0,rows.getLong(1)-sessions.getLong(1))).put("source",rows.getString(2)).put("event",rows.getString(3)).put("fields",new JSONObject(rows.getString(4))));}if(events.length()>0)result.put(new JSONObject().put("id",id).put("version",sessions.getString(2)).put("build",sessions.getString(3)).put("events",events));}}return result;}
    static synchronized void ack(Set<String> ids){for(String id:ids){ContentValues v=new ContentValues();v.put("pending",0);db.update("events",v,"id = ?",new String[]{id});}}
    static synchronized JSONObject credential(String id)throws Exception{JSONObject o=new SecureStore(context).load(),sessions=o.optJSONObject("diagnosticSessions");JSONObject value=sessions==null?null:sessions.optJSONObject(id);return value!=null?value:o.optJSONObject("diagnosticDestination");}
    static synchronized void credential(String id,JSONObject value)throws Exception{saveDestination(id,value);}
}
